python3 - <<'PY'
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
out='/root/output/result.xlsx'
wb=load_workbook(out, data_only=False)
ws=wb['Task']
print('Reopened:', out)
check_cells=['H12','L17','H19','L24','H26','L31','H35','L40','H42','L47','H50','L50']
ok=True
print('\nSpot-check required cells:')
for addr in check_cells:
    v=ws[addr].value
    starts=isinstance(v,str) and v.startswith('=')
    print(f'{addr}: {v} | formula={starts}')
    ok = ok and starts

errors=[]
for ws2 in wb.worksheets:
    for row in ws2.iter_rows():
        for cell in row:
            v=cell.value
            if isinstance(v,str) and ('#NAME?' in v or v.strip() in {'#VALUE!','#REF!','#DIV/0!','#N/A','#NUM!','#NULL!','#NAME?'}) :
                errors.append((ws2.title, cell.coordinate, v))
print('\nLiteral error strings:', errors if errors else 'none')

print('\nFormula samples:')
for addr in ['H12','I13','L17','H19','J22','L24','H26','K29','L31']:
    print(f'{addr}: {ws[addr].value}')
print('\nNet buffer samples:')
for addr in ['H35','J37','L40']:
    print(f'{addr}: {ws[addr].value}')
print('\nSummary samples:')
for addr in ['H42','H43','H44','H45','H46','H47','L46','L47']:
    print(f'{addr}: {ws[addr].value}')
print('\nWeighted mean samples:')
for addr in ['H50','L50']:
    print(f'{addr}: {ws[addr].value}')

# Additional structural validation for all formula targets.
missing=[]
for r1,r2 in [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]:
    for r in range(r1,r2+1):
        for c in range(8,13):
            v=ws.cell(r,c).value
            if not (isinstance(v,str) and v.startswith('=')):
                missing.append(f'{get_column_letter(c)}{r}')
print('\nAll formula target cells populated:', not missing)
if missing:
    print('Missing/non-formulas:', missing)
if not ok or errors or missing:
    raise SystemExit(1)
PY
